<script setup lang="ts">
// the smaller dialogs: shop, chest, stat block, damage, conditions, gifts, journal, keys, invitations
import { computed, ref } from 'vue'
import { app, gs, real, act, close, hands, stage, KEYS, putTokens, onState, openRoom, localLink, newScroll, acceptScroll, kick, toast, leave, saveNow, exportFile, open, dir, travelTo, toggleTorch, setShared } from '../session'
import { CONDITIONS, EFFECTS, ABILITIES, crText, mod, signed, XP_LEVEL } from '../rules/base'
import { monster } from '../rules/monsters'
import { item, ITEMS } from '../rules/items'
import { sheet } from '../rules/hero'
import { rich } from './rich'
import Modal from './Modal.vue'
import MonThumb from './MonThumb.vue'
import Portrait from './Portrait.vue'
import QR from './QR.vue'
import Scan from './Scan.vue'
const me = computed(() => gs.value?.chars[app.seat]); const shop = computed(() => gs.value?.mons[app.modalArg]); const chest = computed(() => gs.value?.chests[app.modalArg]); const M = computed(() => monster(app.modalArg)); const amt = ref(5), kind = ref('slashing'), q = ref(''), stab = ref('buy'); const who = computed(() => gs.value?.chars[app.modalArg] ?? gs.value?.mons[app.modalArg]); const hurt = (k: number) => { const id = app.modalArg; if (k < 0) hands('damage', { who: id, amount: amt.value, type: kind.value }); else hands('heal', { who: id, amount: amt.value }) }
const has = (id: string) => who.value?.conds.some(c => c.id === id); const togC = (id: string) => { const u = app.modalArg; if (has(id)) stage!.R.uncond(u, id); else stage!.R.cond(u, { id, kind: CONDITIONS[id] ? 'cond' : 'fx', until: { unit: u, at: 'end', n: 100 } }); stage!.syncToken(u); onState() }; const found = computed(() => Object.values(ITEMS).filter(i => i.id !== 'unarmed' && (!q.value || i.name.toLowerCase().includes(q.value.toLowerCase()))).slice(0, 60)); const sellable = computed(() => me.value?.inv.filter(s => item(s.id).cost > 0) ?? []); const price = (s: any) => Math.max(1, Math.round(s.price * ((shop.value?.npc?.mood ?? 0) > 50 ? .9 : 1)))
const copied = ref(''), reply = ref(''), scan = ref(false), tab = ref('code'); const copy = async (t: string, k: string) => { try { await navigator.clipboard.writeText(t); copied.value = k; setTimeout(() => copied.value = '', 1500) } catch { toast('Copy it by hand.', true) } }; const took = async () => { if (await acceptScroll(reply.value)) reply.value = '' }; const quests = computed(() => gs.value?.quests ?? []); const camp = computed(() => gs.value?.camp); const quit = async () => { close(); await leave() }; const dmg = (a: any) => a.dmg.map((x: any) => x.join(' ')).join(' + '); void putTokens
const paper = computed(() => { const L = gs.value?.camp?.papers ?? []; return app.modal === 'note' ? L.find(p => p.key === app.modalArg) ?? L[L.length - 1] : null }); const roads = computed(() => ((gs.value?.camp as any)?.places ?? gs.value?.camp?.mod?.list ?? []) as { key: string; name: string; here: boolean }[]); const goTo = (k: string) => { close(); travelTo(k) }; const jt = ref('story')
const setXp = (id: string, v: number) => { const h = real().chars[id]; h.xp = Math.max(0, v); onState() }
</script>
<template>
<Modal v-if="app.modal === 'shop' && shop?.npc" :title="shop.name" :width="620"><div class="row"><Portrait :mon="shop" :model="app.tokens.find(t => t.id === shop!.id)?.m" :size="56" /><span class="grow"><em>{{ shop.npc.role }}</em></span><b>{{ me?.gold ?? 0 }} gold</b></div><div class="tabs" style="margin:10px 0"><button class="tab" :class="{ on: stab === 'buy' }" @click="stab = 'buy'">Buy</button><button class="tab" :class="{ on: stab === 'sell' }" @click="stab = 'sell'">Sell</button></div><div v-if="stab === 'buy'" class="ls"><div v-for="s in shop.npc.stock" :key="s.id" :class="{ no: !s.n }"><span class="grow">{{ item(s.id).name }}<small>{{ item(s.id).text || item(s.id).dmg || (item(s.id).ac ? 'AC ' + item(s.id).ac : '') }}</small></span><small>{{ s.n ? s.n + ' left' : 'sold' }}</small><button class="btn sm" :disabled="!s.n || (me?.gold ?? 0) < price(s)" @click="act({ k: 'buy', npc: shop!.id, item: s.id })">{{ price(s) }} g</button></div></div><div v-else class="ls"><div v-for="s in sellable" :key="s.uid"><span class="grow">{{ item(s.id).name }}{{ s.n > 1 ? ' × ' + s.n : '' }}<small v-if="s.eq">worn</small></span><button class="btn sm" @click="act({ k: 'sell', npc: shop!.id, u: s.uid })">{{ Math.floor(item(s.id).cost * (item(s.id).kind === 'treasure' ? 1 : .5)) }} g</button></div></div></Modal>
<Modal v-else-if="app.modal === 'chest' && chest" title="Chest" :width="420"><p v-if="!chest.loot.length" class="muted">Empty.</p><div class="ls"><div v-for="s in chest.loot" :key="s.uid"><span class="grow">{{ item(s.id).name }}{{ s.n > 1 ? ' × ' + s.n : '' }}<small>{{ item(s.id).text }}</small></span><button class="btn sm" @click="act({ k: 'take', id: chest!.id, u: s.uid })">Take</button></div></div><template #foot><button class="btn primary" :disabled="!chest.loot.length" @click="act({ k: 'take', id: chest!.id }); close()">Take all</button></template></Modal>
<Modal v-else-if="app.modal === 'stat' && M" :title="M.name" :width="560"><div class="row" style="align-items:flex-start;gap:16px"><MonThumb :id="M.id" :size="130" /><div class="grow"><p><em>{{ { T: 'Tiny', S: 'Small', M: 'Medium', L: 'Large', H: 'Huge', G: 'Gargantuan' }[M.size] }} {{ M.type }}, challenge {{ crText(M.cr) }} ({{ M.xp.toLocaleString() }} XP)</em></p><p>Armour class <b>{{ M.ac }}</b>, hit points <b>{{ M.hp }}</b> ({{ M.hd }}), speed <b>{{ M.speed }}</b>{{ M.fly ? ', flies' : '' }}</p><div class="six"><span v-for="(a, i) in ABILITIES" :key="a"><small>{{ a.toUpperCase() }}</small><b>{{ M.ab[i] }}</b><i>{{ signed(mod(M.ab[i])) }}</i></span></div></div></div><div class="rule" /><p v-if="M.res.length || M.physRes"><b>Resists</b> {{ [...M.res, ...(M.physRes ? ['weapons that are not magical'] : [])].join(', ') }}</p><p v-if="M.imm.length"><b>Immune to</b> {{ M.imm.join(', ') }}</p><p v-if="M.vuln.length"><b>Weak to</b> {{ M.vuln.join(', ') }}</p><p><b>Senses</b> passive sight {{ M.pp }}, stealth {{ signed(M.stealth) }}</p><p v-if="M.traits.length"><b>Traits</b> {{ M.traits.map(t => t.replace(/([A-Z])/g, ' $1').replace(/(\d+)/, ' $1').toLowerCase()).join(', ') }}</p><span class="cap">Actions</span><p v-if="M.multi.length"><b><i>Multiattack.</i></b> {{ M.multi.join(', ') }}.</p><p v-for="a in M.acts" :key="a.n"><b><i>{{ a.n.replace(/_/g, ' ') }}{{ a.rc ? ` (recharge ${a.rc >= 6 ? 6 : a.rc + ' to 6'})` : a.uses ? ` (${a.uses} a day)` : '' }}.</i></b> <template v-if="a.hit">{{ signed(a.hit) }} to hit, {{ a.k === 'ranged' ? a.range!.join('/') : a.reach }} ft. </template><template v-if="a.dmg.length">{{ dmg(a) }}. </template><template v-if="a.save && a.k !== 'spell'">{{ a.save.ab.toUpperCase() }} save DC {{ a.save.dc }}{{ a.area ? `, ${a.size}-ft ${a.area}` : '' }}{{ a.save.cond ? `, or ${a.save.cond}` : '' }}{{ a.save.half ? ', half on a success' : '' }}.</template><template v-if="a.grapple"> Grapples.</template></p></Modal>
<Modal v-else-if="app.modal === 'hp' && who" :title="who.name" :width="360"><input v-model.number="amt" class="field" type="number" min="0" style="font-size:24px;text-align:center" aria-label="Amount"><div class="chips" style="margin:8px 0"><button v-for="n in [1, 3, 5, 8, 10, 15, 20, 30]" :key="n" class="chip s" @click="amt = n">{{ n }}</button></div><select v-model="kind" class="field" aria-label="Type"><option v-for="t in ['slashing', 'piercing', 'bludgeoning', 'fire', 'cold', 'lightning', 'thunder', 'acid', 'poison', 'necrotic', 'radiant', 'psychic', 'force']" :key="t">{{ t }}</option></select><template #foot><button class="btn grow" @click="hurt(1)">Heal</button><button class="btn primary grow" @click="hurt(-1)">Damage</button></template></Modal>
<Modal v-else-if="app.modal === 'conds' && who" :title="'Conditions: ' + who.name" :width="560"><div class="chips"><button v-for="(c, k) in CONDITIONS" :key="k" class="chip s" :class="{ on: has(k as string) }" v-tip="c.text" @click="togC(k as string)">{{ c.name }}</button></div><span class="cap">Effects</span><div class="chips"><button v-for="(c, k) in EFFECTS" :key="k" class="chip s" :class="{ on: has(k as string) }" v-tip="c.text" @click="togC(k as string)">{{ c.name }}</button></div></Modal>
<Modal v-else-if="app.modal === 'give' && gs?.chars[app.modalArg]" :title="'Give to ' + gs.chars[app.modalArg].name" :width="560"><div class="row wrap" style="margin-bottom:10px"><button class="btn sm" @click="hands('give_gold', { amount: 50 })">50 gold to all</button><button class="btn sm" @click="hands('inspire', { hero: app.modalArg })">Inspiration</button><button class="btn sm" @click="hands('level_up', { who: app.modalArg })">A level</button><span class="grow" /><label class="tiny muted">XP</label><input class="field" style="width:100px" type="number" :value="gs.chars[app.modalArg].xp" @change="setXp(app.modalArg, +($event.target as HTMLInputElement).value)"></div><input v-model="q" class="field" placeholder="Find an item" aria-label="Find an item"><div class="ls" style="max-height:320px;overflow:auto;margin-top:8px"><div v-for="i in found" :key="i.id"><span class="grow">{{ i.name }}<small>{{ i.text || i.dmg || '' }}</small></span><small>{{ i.rarity ?? '' }}</small><button class="btn sm" @click="hands('give_item', { hero: app.modalArg, item: i.id })">Give</button></div></div></Modal>
<Modal v-else-if="app.modal === 'journal'" :title="camp?.title ?? 'Journal'" :width="760"><div class="tabs" style="margin:-4px 0 16px"><button v-for="t in [['story', 'Story'], ['quests', 'Jobs'], ...(camp?.papers?.length ? [['papers', 'Handouts']] : []), ['count', 'So far']]" :key="t[0]" class="tab" :class="{ on: jt === t[0] }" @click="jt = t[0]">{{ t[1] }}</button></div>
  <template v-if="jt === 'story'"><template v-if="camp"><p class="aloud" v-html="rich(camp.hook)" /><ol class="chs"><li v-for="(c, i) in camp.chapters.filter((c, i) => c.done || i <= camp!.chapter)" :key="i" :class="{ done: c.done }"><b>{{ i + 1 }}</b><span><h3>{{ c.title }}</h3>{{ c.text }}</span></li></ol></template><p v-else class="muted">There is no tale here.</p></template>
  <template v-if="jt === 'quests'"><p v-if="!quests.length" class="muted">Nobody has asked anything of you yet.</p><div v-for="x in quests" :key="x.id" class="qs" :class="x.state"><i class="tick" :class="{ on: x.state !== 'open' }" /><span class="grow"><b>{{ x.name }}</b>{{ x.text }}<template v-if="x.goal.n > 1 && x.state === 'open'"> {{ x.goal.have }} of {{ x.goal.n }}.</template><template v-if="x.state === 'failed'"> Failed.</template></span><small>{{ [x.gold ? x.gold + ' gold' : '', x.xp ? x.xp + ' XP' : ''].filter(Boolean).join(', ') }}</small><button v-if="app.role === 'dm' && x.state === 'open'" class="btn sm" @click="dir!.hands.settle(real().quests.find(q => q.id === x.id)!, true); onState()">Done</button></div></template>
  <template v-if="jt === 'papers'"><div v-for="p in camp!.papers" :key="p.key ?? p.name" class="hand"><h3>{{ p.name }}</h3><p class="aloud" v-html="rich(p.text)" /></div></template>
  <p v-if="jt === 'count' && gs" class="aloud">Day {{ gs.day }}. {{ gs.stats.rooms }} rooms seen, {{ gs.kills }} slain, {{ gs.stats.gold }} gold, {{ gs.stats.crits }} natural twenties and {{ gs.stats.fumbles }} natural ones.</p></Modal>
<Modal v-else-if="app.modal === 'note' && paper" :title="paper.name" :width="620"><div class="hand big"><p class="aloud" v-html="rich(paper.text)" /></div><template #foot><button class="btn primary big" @click="close">Keep it</button></template></Modal>
<Modal v-else-if="app.modal === 'travel'" title="Where to?" :width="520"><p class="muted">{{ app.players.some(p => p.online) && app.seat ? 'The table votes. Everyone goes together.' : 'The whole company goes together.' }}</p><div class="rd"><button v-for="r in roads" :key="r.key" :disabled="r.here || !!gs?.combat" @click="goTo(r.key)"><b>{{ r.name }}</b><small v-if="r.here">You are here</small></button></div></Modal>
<Modal v-else-if="app.modal === 'keys'" title="Keys" :width="520"><div class="ky"><template v-for="k in KEYS.filter(k => !k[2] || (k[2] === 'dm') === (app.role === 'dm'))" :key="k[0]"><kbd>{{ k[0] }}</kbd><span>{{ k[1] }}</span></template></div></Modal>
<Modal v-else-if="app.modal === 'invite'" title="Invite players" :width="560"><p class="muted">Players join from their own phone, tablet or computer, straight to this browser. They choose or make a hero first. Keep this page open while you play.</p><div class="tabs" style="margin-bottom:12px"><button class="tab" :class="{ on: tab === 'code' }" @click="tab = 'code'">Room code</button><button class="tab" :class="{ on: tab === 'scroll' }" @click="tab = 'scroll'">Handshake scroll</button><button class="tab" :class="{ on: tab === 'local' }" @click="tab = 'local'">This device</button></div><template v-if="tab === 'code'"><button v-if="!app.codeState || app.codeState === 'fail'" class="btn primary" @click="openRoom">Open the room</button><p v-if="app.codeState === 'fail'" style="color:var(--bad)">{{ app.codeWhy }} Use a handshake scroll instead.</p><p v-if="app.codeState === 'opening'" class="muted">Opening…</p><template v-if="app.codeState === 'open'"><div class="code sel">{{ app.code }}</div><QR :text="app.invite" /><button class="btn wide" @click="copy(app.invite, 'l')">{{ copied === 'l' ? 'Copied' : 'Copy the link' }}</button></template></template><template v-if="tab === 'scroll'"><p class="muted">Needs no internet between you. Write a scroll, show or send it, and take the reply.</p><button v-if="!app.scroll" class="btn" @click="newScroll">Write a scroll</button><template v-else><p v-if="app.scroll.busy" class="muted">Writing…</p><template v-else><QR :text="app.scroll.text" /><button class="btn wide" @click="copy(app.scroll!.text, 's')">{{ copied === 's' ? 'Copied' : 'Copy the scroll' }}</button><label class="lab">Their reply</label><textarea v-model="reply" class="field" rows="3" /><div class="row" style="margin-top:6px"><button class="btn grow" @click="scan = true">Scan</button><button class="btn primary grow" :disabled="!reply" @click="took">Let them in</button></div><Scan v-if="scan" @found="t => { scan = false; reply = t; took() }" @close="scan = false" /></template></template></template><template v-if="tab === 'local'"><p class="muted">For a second window or screen on this computer.</p><button class="btn wide" @click="copy(localLink(), 'd')">{{ copied === 'd' ? 'Copied' : 'Copy the link' }}</button></template><template v-if="app.players.length"><span class="cap">At the table</span><div v-for="p in app.players" :key="p.pid" class="row" style="padding:4px 0"><Portrait :hero="gs?.chars[p.token]" :size="34" /><span class="grow">{{ p.hero }} <span class="dim">{{ p.name !== p.hero ? p.name : '' }}{{ p.online ? '' : ', away' }}</span></span><button class="btn sm quiet" @click="kick(p)">Remove</button></div></template></Modal>
<Modal v-else-if="app.modal === 'menu'" :title="gs?.camp?.title ?? app.worldName" :width="420"><div class="mn"><button v-if="app.seat" @click="open('sheet')">Record sheet<kbd>C</kbd></button><button @click="open('journal')">Journal<kbd>J</kbd></button><button v-if="roads.length > 1" @click="open('travel')">Travel</button><button v-if="app.hosting" @click="open('invite')">Invite players</button><button v-if="app.role === 'dm' && !app.seat" @click="setShared({ paused: !app.shared.paused }); close()">{{ app.shared.paused ? 'Resume the game' : 'Pause the game' }}<kbd>P</kbd></button><button @click="toggleTorch(); close()">{{ app.torch ? 'Put out the torch' : 'Light the torch' }}<kbd>T</kbd></button><button @click="open('settings')">Settings and dice</button><button @click="open('keys')">Keys<kbd>?</kbd></button><button v-if="app.hosting" @click="saveNow().then(() => toast('Saved.')); close()">Save now<kbd>Ctrl S</kbd></button><button v-if="app.hosting" @click="exportFile">Write to a file</button><button @click="quit">Leave the table</button></div></Modal>
</template>
<style scoped>.ls>div{display:flex;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid var(--line2)}.ls small{font-size:15px;line-height:1.2;color:var(--ink2);display:block}.ls .no{opacity:.45}.six{display:grid;grid-template-columns:repeat(6,1fr);border:2px solid var(--ink);margin-top:8px}.six span{text-align:center;border-right:2px solid var(--ink);padding:4px 0}.six span:last-child{border:0}.six small{display:block;font-size:13.5px;color:var(--ink2)}.six b{display:block;font:800 24px/1 var(--serif)}.six i{font-style:normal;font-size:15px}.chs{list-style:none;padding:0;margin:18px 0 0;border-top:3px solid var(--ink)}.chs li{display:flex;gap:16px;padding:10px 0;border-bottom:1px solid var(--line2)}.chs b{font:800 38px/.9 var(--serif);width:38px;flex:none}.chs h3{margin-bottom:3px}.chs .done{color:var(--ink3)}.qs{display:flex;gap:13px;padding:9px 0;align-items:flex-start;border-bottom:1px solid var(--line2)}.qs .tick{margin-top:3px}.qs b{display:block;font:700 20px/1.1 var(--serif)}.qs.done,.qs.failed{opacity:.5}.qs small{font-size:15.5px;white-space:nowrap}.hand{border:2px solid var(--ink);padding:16px 20px 8px;margin-bottom:14px;background:#fff}.hand h3{margin-bottom:8px}.hand .aloud{white-space:pre-wrap}.hand.big .aloud{font-size:22px}.rd{border-top:3px solid var(--ink);margin-top:10px}.rd button{display:flex;width:100%;align-items:baseline;gap:12px;padding:10px 6px;border-bottom:1px solid var(--line2)}.rd b{font:700 23px/1 var(--serif);flex:1}.rd button:hover:not(:disabled){background:var(--spot);color:var(--on-spot)}.rd button:disabled{color:var(--ink3)}.ky{display:grid;grid-template-columns:max-content 1fr;gap:9px 18px;align-items:center}.ky kbd{justify-self:end}.code{font:800 46px/1.2 var(--serif);text-align:center;border:3px solid var(--ink);padding:6px 10px 12px;margin-bottom:12px}.mn{margin:-18px -20px}.mn button{display:flex;align-items:center;gap:12px;width:100%;padding:9px 20px;border-bottom:1px solid var(--line);font-size:19px}.mn button:hover{background:var(--spot);color:var(--on-spot)}.mn kbd{margin-left:auto}</style>
